    private static PolymerPonderScene.Definition scene109() {
        return
        PolymerPonderScene.builder("fluid_pipe_flow", "create:fluid_pipe", "Moving Fluids using Copper Pipes", "create:fluid_pipe/flow")
            .configureBasePlate(0, 0, 5)
            .showSection(s -> s.fromTo(0, 0, 0, 4, 0, 4), PolymerPonderScene.Fade.UP)
            .idle(5)
            .setBlocks(s -> s.position(2, 1, 1), "create:fluid_pipe", "down=false", "east=true", "north=false", "south=false", "up=false", "waterlogged=false", "west=true")
            .setBlocks(s -> s.position(1, 1, 2), "create:fluid_pipe", "down=false", "east=false", "north=true", "south=true", "up=false", "waterlogged=false", "west=false")
            .showSection(s -> s.fromTo(4, 1, 2, 4, 2, 2), PolymerPonderScene.Fade.DOWN)
            .idle(5)
            .showSection(s -> s.fromTo(0, 1, 3, 0, 2, 3), PolymerPonderScene.Fade.DOWN)
            .simulate("{\"action\": \"blockEntity\", \"body\": [{\"e\": {\"a\": [{\"a\": [{\"c\": [\"net.minecraft.world.level.material.Fluids\"], \"k\": \"static\", \"n\": \"LAVA\"}, {\"k\": \"lit\", \"t\": \"int\", \"v\": 810000}], \"c\": [\"com.zurrtum.create.infrastructure.fluids.FluidStack\"], \"k\": \"new\"}], \"k\": \"call\", \"n\": \"insert\", \"o\": {\"a\": [], \"k\": \"call\", \"n\": \"getTankInventory\", \"o\": {\"k\": \"param\"}}}, \"s\": \"expr\"}], \"nbt\": false, \"positions\": [[4, 1, 2]], \"type\": [\"com.zurrtum.create.content.fluids.tank.FluidTankBlockEntity\"]}")
            .idle(10)
            .showSection(s -> s.position(4, 1, 1), PolymerPonderScene.Fade.SOUTH)
            .idle(3)
            .showSection(s -> s.position(3, 1, 1), PolymerPonderScene.Fade.EAST)
            .idle(3)
            .showSection(s -> s.position(2, 1, 1), PolymerPonderScene.Fade.EAST)
            .idle(3)
            .showSection(s -> s.position(1, 1, 1), PolymerPonderScene.Fade.EAST)
            .idle(3)
            .text(60, "Fluid Pipes can connect two or more fluid sources and targets")
            .pointAt(1.5f, 2.0f, 1.5f)
            .keyframe()
            .showSection(s -> s.position(1, 1, 2), PolymerPonderScene.Fade.NORTH)
            .idle(3)
            .showSection(s -> s.position(1, 1, 3), PolymerPonderScene.Fade.NORTH)
            .idle(3)
            .idle(60)
            .idle(7)
            .restoreBlocks(s -> s.position(2, 1, 1))
            .keyframe()
            .text(70, "Using a wrench, a straight pipe segment can be given a window")
            .pointAt(2.5f, 1.5f, 1.5f)
            .idle(40)
            .idle(7)
            .restoreBlocks(s -> s.position(1, 1, 2))
            .idle(40)
            .showSection(s -> java.util.stream.Stream.concat((s.fromTo(2, 1, 2, 2, 2, 2)).stream(), (s.fromTo(1, 2, 2, 1, 3, 2)).stream()).distinct().toList(), PolymerPonderScene.Fade.DOWN)
            .idle(10)
            .idle(1)
            .idle(10)
            .keyframe()
            .text(55, "Windowed pipes will not connect to any other adjacent pipe segments")
            .pointAt(2.5f, 1.5f, 2.5f)
            .idle(60)
            .hideSection(s -> java.util.stream.Stream.concat((s.fromTo(2, 1, 2, 2, 2, 2)).stream(), (s.fromTo(1, 2, 2, 1, 3, 2)).stream()).distinct().toList(), PolymerPonderScene.Fade.UP)
            .idle(10)
            .setBlocks(s -> s.position(3, 1, 1), "create:mechanical_pump", "facing=west", "waterlogged=false")
            .idle(10)
            .showSection(s -> s.position(5, 0, 1), PolymerPonderScene.Fade.UP)
            .showSection(s -> s.fromTo(5, 1, 0, 3, 1, 0), PolymerPonderScene.Fade.SOUTH)
            .idle(10)
            .multiplySpeed(s -> s.everywhere(), 0.25f)
            .speed(s -> s.position(3, 1, 1), 8.0f)
            .simulate("{\"action\": \"blockEntity\", \"body\": [{\"e\": {\"a\": [{\"k\": \"lit\", \"t\": \"int\", \"v\": 0}], \"k\": \"call\", \"n\": \"onSpeedChanged\", \"o\": {\"k\": \"param\"}}, \"s\": \"expr\"}], \"nbt\": false, \"positions\": [[3, 1, 1]], \"type\": [\"com.zurrtum.create.content.fluids.pump.PumpBlockEntity\"]}")
            .keyframe()
            .text(70, "Powered by Mechanical Pumps, the Pipes can transport Fluids")
            .pointAt(3.5f, 2.0f, 1.5f)
            .idle(85)
            .text(40, "No fluid is being extracted at first")
            .pointAt(4.5f, 2.0f, 2.5f)
            .outlineCaption(4.0f, 1.0f, 2.0f, 5.0f, 3.0f, 3.0f, 0xFF5D6C)
            .idle(70)
            .outline(4.0f, 1.0f, 2.0f, 5.0f, 3.0f, 3.0f, 0x8CBA51, 5)
            .idle(5)
            .outline(0.0f, 1.0f, 3.0f, 1.0f, 3.0f, 4.0f, 0x8CBA51, 100)
            .idle(5)
            .keyframe()
            .text(100, "Once the flow connects them, the endpoints gradually transfer their contents")
            .multiplySpeed(s -> s.everywhere(), 2.0f)
            .simulate("{\"action\": \"blockEntity\", \"body\": [{\"e\": {\"a\": [{\"k\": \"lit\", \"t\": \"int\", \"v\": 0}], \"k\": \"call\", \"n\": \"onSpeedChanged\", \"o\": {\"k\": \"param\"}}, \"s\": \"expr\"}], \"nbt\": false, \"positions\": [[3, 1, 1]], \"type\": [\"com.zurrtum.create.content.fluids.pump.PumpBlockEntity\"]}")
            .idle(120)
            .text(60, "Thus, the Pipe blocks themselves never 'physically' contain any fluid")
            .pointAt(1.5f, 2.0f, 1.5f)
            .idle(50)
            .build();
    }
